import { Link } from 'react-router-dom';
import Header from '../components/Header';
import Footer from '../components/Footer';

const Home = () => {
    return (
        <div className="min-h-screen flex flex-col font-body-md text-body-md text-on-surface bg-surface dark:bg-surface-dim">
            <Header />
            <main className="flex-grow flex items-center justify-center px-margin-mobile py-24">
                <div className="w-full max-w-[440px] flex flex-col gap-8">
                    {/* Login Card */}
                    <div className="bg-roe border border-outline-variant rounded-lg p-8 md:p-10 shadow-sm">
                        <div className="text-center mb-10">
                            <h1 className="font-headline-lg text-headline-lg text-primary mb-2">You can Either Login if you Already have a account or Signup for a new account</h1>
                        </div>
                        <div className='flex gap-4 justify-center'>
                            <Link to="/login"><div className="w-full flex items-center justify-center p-4 bg-primary text-on-primary rounded-md">Login</div></Link>
                            <Link to="/signup"><div className="w-full flex items-center justify-center p-4 bg-primary text-on-primary rounded-md">Signup</div></Link>
                        </div>
                    </div>
                </div>
            </main>
            <Footer />
        </div>
    );
};

export default Home;
